"""Paper artifacts for the FP error-analysis section (RELEVER §6 "Anatomy" + appendix).

Single source of truth for the FP-composition numbers that enter the paper. Recomputes
everything from ``data/fp_taxonomy/`` via the join in ``fp_subset_report.py`` (no CSV
intermediary), cross-checks the population stats JSON, then:

  * writes the three auto-generated table bodies under ``paper/sections/tables/``:
      - ``fp_cells_rows.tex``    (8-cell composition, grouped by intro failure mode)
      - ``fp_rbucket_rows.tex``  (union composition x R_q bucket)
      - ``fp_rank_rows.tex``     (per-(pair, system) slots x first-stage rank bin)
  * recomputes the judge-validation headline vs the 100-pair human gold, and
  * prints the ``\\statFp*`` macro block to paste into ``paper/macros.tex``
    (same manual-paste convention as ``paper_stats.py``).

    uv run python src/process_results/fp_paper_stats.py
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(PROJECT_ROOT))

from src.create_dataset.classifying_data.batch_api.label_fp_taxonomy_batch import (  # noqa: E402
    PILOT_DIR,
)
from src.create_dataset.classifying_data.fp_subset_report import (  # noqa: E402
    CELLS,
    R_BUCKET_ORDER,
    RANK_BINS,
    _composition,
    _rank_bin,
    composition_by,
    join_predictions,
    load_population,
)
from src.create_dataset.classifying_data.fp_taxonomy_agreement import (  # noqa: E402
    cohen_kappa,
    load_gold,
)
from src.create_dataset.classifying_data.fp_taxonomy_prompt import (  # noqa: E402
    BITS,
    FP_TAXONOMY_PROMPT_VERSION,
)
from src.retrieval.config import FP_TAXONOMY_DATA_PATH  # noqa: E402

SUBSET_DIR = FP_TAXONOMY_DATA_PATH / "subset_2sys"
GENERATED_DIR = PROJECT_ROOT / "paper" / "sections" / "tables"
HEADER = "% AUTO-GENERATED by src/process_results/fp_paper_stats.py — do not edit.\n"

COLBERT = "colbert-v2"
ICT = "ICT-TIME-and-Querit-embedding-v1"

# tab:fpcells row order, grouped by the intro's failure modes:
# mode 1 (both entity slots) | mode 2 (relation elsewhere) | mode 3 (constant only) | residual.
CELL_GROUPS: tuple[tuple[tuple[bool, bool, bool], ...], ...] = (
    ((True, True, True), (True, False, True)),
    ((True, True, False), (False, True, True), (False, True, False)),
    ((False, False, True),),
    ((True, False, False), (False, False, False)),
)
GROUPED_CELLS = tuple(c for grp in CELL_GROUPS for c in grp)


def num(n: int) -> str:
    return f"{n:,}".replace(",", "{,}")


def pct(x: float) -> str:
    return f"{100 * x:.1f}\\%"


def share(x: float) -> str:
    return f"{100 * x:.1f}"


def _check(v: bool) -> str:
    return "\\checkmark" if v else "---"


def _bin_label(name: str) -> str:
    return {"1-3": "1--3", "4-10": "4--10", ">10": "$>$10"}.get(
        name, name.replace("-", "--"))


def cross_check(pop: list[dict], missing: int) -> None:
    stats_path = SUBSET_DIR / "subset_population_stats.json"
    stats = json.loads(stats_path.read_text())
    n_expected = stats["n_unique_fp_pairs"]
    per_sys = stats["pairs_per_system"] if "pairs_per_system" in stats else None
    problems = []
    if len(pop) != n_expected:
        problems.append(f"population rows {len(pop)} != stats {n_expected}")
    if missing:
        problems.append(f"{missing} pairs lack {FP_TAXONOMY_PROMPT_VERSION} predictions")
    for sys_alias in (COLBERT, ICT):
        n_sys = sum(1 for p in pop if sys_alias in p["systems"])
        expected = per_sys.get(sys_alias) if per_sys else 10290
        if n_sys != expected:
            problems.append(f"{sys_alias}: {n_sys} pairs != expected {expected}")
    if problems:
        raise SystemExit("CROSS-CHECK FAILED:\n  " + "\n  ".join(problems))


def judge_validation() -> dict:
    """Exact-cell agreement of the pipeline judge (gpt-5.2 x v5) vs the human gold."""
    gold = load_gold(PILOT_DIR / "fp_human__gold.jsonl")
    preds: dict[str, dict] = {}
    for line in (PILOT_DIR / "model_compare" / "gpt-5.2__v5.jsonl").read_text().splitlines():
        if line.strip():
            rec = json.loads(line)
            preds[rec["id"]] = rec
    joined = [(g, preds[g["id"]]) for g in gold if g["id"] in preds]
    n = len(joined)

    def cell(r: dict) -> str:
        return "/".join("1" if r[b] else "0" for b in BITS)

    cell_pairs: list[tuple[str, str]] = [(cell(g), cell(p)) for g, p in joined]
    bit_kappas = [cohen_kappa([(str(g[b]), str(p[b])) for g, p in joined]) for b in BITS]
    return {
        "n": n,
        "cell_agree": sum(1 for a, b in cell_pairs if a == b) / n,
        "cell_kappa": cohen_kappa(cell_pairs),
        "mean_bit_kappa": sum(bit_kappas) / len(bit_kappas),
    }


def write_cells_rows(comps: dict[str, dict]) -> None:
    lines = [HEADER]
    for gi, grp in enumerate(CELL_GROUPS):
        for c in grp:
            checks = " & ".join(_check(v) for v in c)
            shares = " & ".join(share(comps[g]["shares"][c]) for g in (COLBERT, ICT, "union"))
            lines.append(f"{checks} & {shares} \\\\\n")
        if gi < len(CELL_GROUPS) - 1:
            lines.append("\\addlinespace\n")
    (GENERATED_DIR / "fp_cells_rows.tex").write_text("".join(lines))


def write_breakdown_rows(fname: str, comps_by: dict[str, dict],
                         order: tuple[str, ...]) -> None:
    lines = [HEADER]
    for name in order:
        if name not in comps_by:
            continue
        c = comps_by[name]
        cells = " & ".join(share(c["shares"][cell]) for cell in GROUPED_CELLS)
        lines.append(f"{_bin_label(name)} & {num(c['n'])} & {cells} & "
                     f"{share(c['instance_and_constant'])} \\\\\n")
    (GENERATED_DIR / fname).write_text("".join(lines))


def main() -> None:
    pop = load_population(SUBSET_DIR / "subset_population.jsonl")
    joined, missing = join_predictions(pop, FP_TAXONOMY_PROMPT_VERSION)
    cross_check(pop, missing)

    comps = {
        "union": _composition(joined),
        COLBERT: _composition([r for r in joined if COLBERT in r["systems"]]),
        ICT: _composition([r for r in joined if ICT in r["systems"]]),
    }
    rb_comps = composition_by(joined, lambda r: (r["r_bucket"],))
    rank_comps = composition_by(
        joined, lambda r: tuple(_rank_bin(int(k)) for k in r["systems"].values()))

    GENERATED_DIR.mkdir(parents=True, exist_ok=True)
    write_cells_rows(comps)
    write_breakdown_rows("fp_rbucket_rows.tex", rb_comps, R_BUCKET_ORDER)
    write_breakdown_rows("fp_rank_rows.tex", rank_comps, RANK_BINS)
    for f in ("fp_cells_rows.tex", "fp_rbucket_rows.tex", "fp_rank_rows.tex"):
        print(f"-> {GENERATED_DIR / f}")

    u = comps["union"]
    rel_elsewhere = sum(u["shares"][c] for c in
                        ((True, True, False), (False, True, True), (False, True, False)))
    residual = sum(u["shares"][c] for c in
                   ((True, False, False), (False, False, False)))
    overlap = sum(1 for p in pop if p["n_systems"] == 2) / len(pop)
    jv = judge_validation()

    print("\n== Suggested macros.tex values (\\statFp*) ==")
    macros = [
        ("statFpNPairs", num(u["n"])),
        ("statFpNPerSys", num(comps[COLBERT]["n"])),
        ("statFpBothEnt", pct(u["instance_and_constant"])),
        ("statFpAllPresent", pct(u["all_present"])),
        ("statFpRightEntWrongRel", pct(u["right_entities_wrong_relation"])),
        ("statFpRelElsewhere", pct(rel_elsewhere)),
        ("statFpConstOnly", pct(u["shares"][(False, False, True)])),
        ("statFpResidual", pct(residual)),
        ("statFpNone", pct(u["shares"][(False, False, False)])),
        ("statFpOverlap", pct(overlap)),
        ("statFpColbertAll", pct(comps[COLBERT]["all_present"])),
        ("statFpIctAll", pct(comps[ICT]["all_present"])),
        ("statFpColbertInstOnly", pct(comps[COLBERT]["shares"][(True, False, False)])),
        ("statFpIctInstOnly", pct(comps[ICT]["shares"][(True, False, False)])),
        ("statFpGoldN", str(jv["n"])),
        ("statFpCellAgree", pct(jv["cell_agree"])),
        ("statFpCellKappa", f"{jv['cell_kappa']:.3f}"),
        ("statFpMeanBitKappa", f"{jv['mean_bit_kappa']:.3f}"),
    ]
    for name, val in macros:
        print(f"\\newcommand{{\\{name}}}{{{val}\\xspace}}")

    # Guard rails: the paper quotes generator-exact values only.
    both_count = u["cells"][(True, True, True)] + u["cells"][(True, False, True)]
    print(f"\n(both-entity-slots exact: {both_count}/{u['n']} = "
          f"{100 * u['instance_and_constant']:.2f}% -> quoted {pct(u['instance_and_constant'])})")


if __name__ == "__main__":
    main()
